def event(thread="expected",time="2026-10-14T20:00:30Z",kind="CommandExecution",status="completed"):
 return {"timestamp":time,"type":"event_msg","payload":{"type":"item_completed","thread_id":thread,"item":{"type":kind,"status":status,"id":"synthetic"}}}
def data(events): return b"\n".join(json.dumps(x).encode() for x in events)
r=v.inspect_transcript(data([meta,event(),event(kind="FileChange"),event(thread="wrong"),event(time="2026-10-14T19:59:59Z")]),"expected",w,start,end); assert r["command_count"]==1 and r["file_change_count"]==1 and r["unqualified_completed_tool_events"]==2
for events in ([meta,event(time="2026-10-14T19:59:59Z")],[meta,event(thread="wrong")],[event()],[meta,event(status="failed")]):
 try: v.inspect_transcript(data(events),"expected",w,start,end)
 except ValueError: pass
 else: raise AssertionError("invalid capture accepted")
